SELECT

FROM travel_plan_chat_messages c
         LEFT JOIN travel_plan_members m ON m.id = c.sender_member_id
WHERE c.travel_plan_id = #{travelPlanId}

ORDER BY c.id DESC
LIMIT #{limit}

SELECT

FROM travel_plan_chat_messages c
         LEFT JOIN travel_plan_members m ON m.id = c.sender_member_id
WHERE c.travel_plan_id = #{travelPlanId}
  AND c.id < #{beforeMessageId}

ORDER BY c.id DESC
LIMIT #{limit}

SELECT

FROM travel_plan_chat_messages c
         LEFT JOIN travel_plan_members m ON m.id = c.sender_member_id
WHERE c.id = #{id}
  AND c.travel_plan_id = #{travelPlanId}

SELECT MAX(id)
FROM travel_plan_chat_messages
WHERE travel_plan_id = #{travelPlanId}

SELECT 
FROM travel_plan_chat_messages c LEFT JOIN travel_plan_members m ON m.id = c.sender_member_id
WHERE c.travel_plan_id = #{travelPlanId} AND c.sender_member_id = #{senderMemberId}
  AND c.client_request_id = #{clientRequestId}

mapper.update:
UPDATE travel_plan_chat_messages
SET deleted_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND travel_plan_id = #{travelPlanId}
  AND sender_member_id = #{senderMemberId}
  AND deleted_at IS NULL

